  var legacy=new CompoundTag();NativeStorageSettings.fresh().write(legacy);legacy.putInt("MainTextureLayout",2);legacy.putBoolean("SlabTileSides",true);legacy.putInt("SideTexture",37);var previous=NativeStorageSettings.read(legacy);var preserved=new NativeStorageEdit(pos,7,7,2,true,new int[]{-1,1,3,-1,4,7}).apply(previous);need(preserved.housing().tileSides&&preserved.housing().sideTexture==37,"face/main edits preserve untouched legacy side flags and material");
  var edit=new NativeStorageEdit(pos,7,295,2,true,new int[]{-1,1,3,-1,4,7});byte[] bytes;var b=buffer(level);try{edit.encode(b);need(b.readableBytes()==42,"fixed42byte edit");bytes=new byte[42];b.getBytes(0,bytes);var copy=NativeStorageEdit.decode(b);need(copy.pos().equals(pos)&&copy.window()==7&&copy.main()==295&&java.util.Arrays.equals(copy.faces(),edit.faces()),"actual registry codec roundtrip");var faces=copy.faces();faces[0]=99;need(copy.faces()[0]==-1,"immutable face ownership");}finally{b.release();}
